import {courseLesson,edit} from './utility-authoring.js';
const L=(...args)=>courseLesson("command",...args);
export const commandUtilsLessons=[
L("budget","Check the task budget before yielding",[7, 8],"<p>These helpers consider fewer than 4,000 ticks or fewer than two execution seconds low. Calling them consumes ticks. <code>suspend_if_needed()</code> yields only when necessary and may account for server lag. The browser has its own educational scheduling limits; it is not the server scheduler.</p>","before = ticks_left();\nlow = $command_utils:running_out_of_time();\nyielded = $command_utils:suspend_if_needed(0);\nafter = ticks_left();\nplayer:tell(\"TICKS before: \", toliteral(before));\nplayer:tell(\"LOW budget: \", toliteral(low));\nplayer:tell(\"YIELDED: \", toliteral(yielded));\nplayer:tell(\"TICKS after: \", toliteral(after));",edit("suspend_if_needed(0)","suspend_if_needed(1)","Request a one-second minimum delay if a yield is needed. With a healthy budget it still does not suspend."),{"server": {"names": ["running_out_of_time", "suspend_if_needed"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "Both tick balances are printed. A healthy task reports false for low budget and yielding, with a lower ending balance. A low-budget call yields and gets a replenished task budget."}}),
L("input","Read one response and a yes/no answer",[2, 4, 16],"<p>Connection input belongs to a command task. <code>read()</code> prompts and handles @abort; <code>yes_or_no()</code> accepts prefixes of yes/no and returns error values for blank or invalid responses. <code>reading_input()</code> reads a core-maintained flag, not the socket itself. The Code tab below only inspects source.</p>","player:tell(\"READING flag before: \", $command_utils:reading_input(player));\nanswer = $command_utils:read(\"a tool name\");\nplayer:tell(\"TOOL response: \", toliteral(answer));\nconfirmed = $command_utils:yes_or_no(\"Keep this tool?\");\nplayer:tell(\"CONFIRMED: \", toliteral(confirmed));",edit("a tool name","a room name","Change the prompt and enter a room name. Try a blank yes/no response to see <code>E_NONE</code> rather than treating every response as false."),{"server": {"names": ["read", "yes_or_no", "reading_input"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "Enter brush, then yes. The labeled response is \"brush\" and confirmation is 1. Enter no to get 0; @abort terminates the task."}}),
L("multiple-lines","Read multiple lines and understand escaping",[3, 5, 9],"<p>This ToastCore routes <code>read_lines()</code> to its inline editor; its older dot-terminated loop is unreachable. <code>read_lines_escape()</code> still provides a dot-terminated loop with custom escapes and help. <code>dump_lines()</code> doubles leading periods and quotes @abort for that legacy protocol.</p>","lines = {\"brush\", \".\", \"@abort\"};\nplayer:tell(\"QUOTED input: \", toliteral($command_utils:dump_lines(lines)));\nplayer:tell(\"ENTER lines; type done to finish:\");\nresult = $command_utils:read_lines_escape(\"done\", \"Enter one tool per line.\");\nplayer:tell(\"CAPTURED: \", toliteral(result));\nplayer:tell(\"OPEN inline editor:\");\nedited = $command_utils:read_lines();\nplayer:tell(\"EDITED: \", toliteral(edited));",edit("\"done\"","\"finish\"","Use finish as the custom terminator. The returned terminator string changes; the entered lines remain data."),{"server": {"names": ["read_lines", "read_lines_escape", "dump_lines"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "Enter brush then done in the escape loop: CAPTURED is {\"done\", {\"brush\"}}. The separate inline editor follows its displayed save/cancel controls."}}),
L("quoting","Prepare text for a dot-terminated input loop",[9],"<p>When sending data back through a legacy line reader, quote its control lines. This helper produces data plus the final terminator; it does not send anything or start a read task.</p>","lines = {\"brush\", \".\", \"@abort\"};\nencoded = $command_utils:dump_lines(lines);\nplayer:tell(\"ENCODED lines:\");\nfor line in (encoded)\n  player:tell(toliteral(line));\nendfor",edit("\"brush\"","\"..brush\"","Start the first line with two periods. The encoder adds one leading period, preserving the original data after decoding.")),
L("feedback","Report failed object and player matches",[0, 1],"<p>Matching failures are sentinel objects. These helpers print messages and return failure information; check it before continuing the command. The player-result alias can process several results and returns the overall flag followed by successful players.</p>","player:tell(\"OBJECT feedback:\");\nplayer:tell(\"OBJECT failed: \", toliteral($command_utils:object_match_failed($failed_match, \"brush\")));\nplayer:tell(\"PLAYER feedback:\");\nplayer:tell(\"PLAYER failed: \", toliteral($command_utils:player_match_failed($nothing, \"\")));\nplayer:tell(\"PLAYER results: \", toliteral($command_utils:player_match_result({player}, {\"me\"})));",edit("$failed_match, \"brush\"","$nothing, \"\"","Use an empty object name. The object feedback asks for a name rather than reporting a missing brush.")),
L("task","Inspect a queued task",[12],"<p><code>task_info()</code> searches queued task records and returns E_INVARG when the task is absent. A running task is not necessarily queued. Queue visibility follows the caller\u2019s permissions. Task IDs and timing are live-server data.</p>","id = -1;\nplayer:tell(\"TASK information: \", toliteral($command_utils:task_info(id)));",edit("id = -1;","id = -2;","Try a second impossible task ID. Both return E_INVARG."),{"server": {"names": ["task_info"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("yield-delimiters","Yield while preserving client output boundaries",[6, 14],"<p>The suspend wrapper can close and reopen client output delimiters around a yield. Its string form prints the closing delimiter without suspending. <code>kill_if_laggy()</code> ends the current task when the measured server lag exceeds your threshold. Real-server delays are not limited to the playground\u2019s five-second cap.</p>","player:tell(\"BEFORE yield\");\ndelimiters = $command_utils:suspend(0, 1);\nplayer:tell(\"AFTER yield, delimiters: \", toliteral(delimiters));\n$command_utils:suspend(0, delimiters[2]);\n$command_utils:kill_if_laggy(60, \"Stopping because this test server is lagging.\");\nplayer:tell(\"Lag check completed.\");",edit("suspend(0, 1)","suspend(1, 1)","Wait at least one second in the first yield. The continuation still prints after resumption."),{"server": {"names": ["suspend", "kill_if_laggy"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "The before line precedes suspension and the after line appears on resumption. The lag check prints its final line only if the task was not killed."}}),
L("dispatch","Follow command fallback and feature validation",[10, 11, 15],"<p>Command fallback consults player and room feature hooks before printing a failure and suggesting syntax. <code>validate_feature()</code> compares the current parsed command and task identity with the snapshot recorded by <code>do_huh()</code>; it is not general authentication. Do not suspend between dispatch and validation.</p>","player:tell(\"DISPATCH unknown command:\");\n$command_utils:do_huh(\"utility-practice-unknown\", {});\nplayer:tell(\"SYNTAX suggestion: \", toliteral($command_utils:explain_syntax(player.location, \"utility-practice-unknown\", {})));\nplayer:tell(\"FEATURE validation: \", toliteral($command_utils:validate_feature(\"utility-practice-unknown\", {})));",edit("utility-practice-unknown","another-practice-command","Change the command name consistently. An unhandled command still reaches fallback; feature validation follows the new recorded name."),{"server": {"names": ["do_huh", "explain_syntax", "validate_feature"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "With no feature handling that name, fallback prints that the command is not understood. Validation reflects whether the same parser context and task are still active."}}),
L("prompt-report","Build a small command interaction",[],"<p>Separate reading, validating and reporting. A returned error value must be handled before treating a response as text. Keep prompts and final results labeled so the learner can follow each stage.</p>","answer = $command_utils:read(\"a short label\");\nif (typeof(answer) == ERR)\n  player:tell(\"INPUT error: \", toliteral(answer));\nelse\n  player:tell(\"LABEL: \", $string_utils:trim(answer));\nendif",edit("a short label","a project name","Change the prompt, then enter a padded project name. The final label trims the surrounding whitespace."),{"server": {"names": ["read"], "prerequisites": "A disposable local ToastStunt server with the full pinned ToastCore, outbound networking disabled and only test accounts connected. Run from a command verb on your test player, not emergency Eval.", "manual": true, "expectedEffect": "Enter two spaces, Workshop, then two spaces. The final labeled output is LABEL: Workshop. @abort stops the command instead of printing a label."}}),
];
export const commandExclusions={"13": "Core initialization hook resets scheduler and feature bookkeeping; not an ordinary command utility API."};
